import re
import pandas as pd
def task_func(json_str):
    if not json_str:
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict) or not data:
        return pd.DataFrame()
    normalized = {}
